#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 1000000007;
constexpr int MAX_S = (1 << 20) + 5;

int n, L, res;
int arr1[MAX_S], arr2[MAX_S];
int con[10][10], val[10][10], mask[10][10][10];

long long mpow(long long b, long long e) {
    long long r = 1;
    for (; e; e >>= 1, b = b * b % MOD)
        if (e & 1) r = r * b % MOD;
    return r;
}

long long minv(long long x) { return mpow(x, MOD - 2); }

bool chk(int x, int y, int z) {
    int v[3] = {x, y, z};
    int p[3] = {0, 1, 2};
    do {
        if (con[v[p[0]]][1] && con[v[p[1]]][2] && con[v[p[2]]][3]) return true;
    } while (next_permutation(p, p + 3));
    return false;
}

void dfsA(int coef, int r, int c) {
    if (r == 7 && c == 1) {
        int st = 0;
        for (int i = 1; i <= 6; ++i)
            for (int j = i + 1; j <= 6; ++j)
                for (int k = j + 1; k <= 6; ++k)
                    if (chk(i, j, k)) {
                        int x = 1;
                        while (x == i || x == j || x == k) ++x;
                        int y = x + 1;
                        while (y == i || y == j || y == k) ++y;
                        int z = y + 1;
                        while (z == i || z == j || z == k) ++z;
                        st |= mask[x][y][z];
                    }
        arr1[st] = (arr1[st] + coef) % MOD;
        return;
    }

    con[r][c] = 1;
    if (c == 3) dfsA(1LL * coef * val[r][c] % MOD, r + 1, 1);
    else dfsA(1LL * coef * val[r][c] % MOD, r, c + 1);
    con[r][c] = 0;

    if (c == 3) dfsA(1LL * coef * (MOD + 1 - val[r][c]) % MOD, r + 1, 1);
    else dfsA(1LL * coef * (MOD + 1 - val[r][c]) % MOD, r, c + 1);
}

void dfsB(int coef, int r, int c) {
    if (r == 7 && c == 4) {
        int st = 0;
        for (int i = 1; i <= 6; ++i)
            for (int j = i + 1; j <= 6; ++j)
                for (int k = j + 1; k <= 6; ++k)
                    if (chk(i, j, k)) st |= mask[i][j][k];
        arr2[st] = (arr2[st] + coef) % MOD;
        res = (res + 1LL * arr1[L ^ st] * coef) % MOD;
        return;
    }

    con[r][c - 3] = 1;
    if (c == 6) dfsB(1LL * coef * val[r][c] % MOD, r + 1, 4);
    else dfsB(1LL * coef * val[r][c] % MOD, r, c + 1);
    con[r][c - 3] = 0;

    if (c == 6) dfsB(1LL * coef * (MOD + 1 - val[r][c]) % MOD, r + 1, 4);
    else dfsB(1LL * coef * (MOD + 1 - val[r][c]) % MOD, r, c + 1);
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            int t; scanf("%d", &t);
            val[i][j] = 1LL * t * minv(100) % MOD;
        }
    for (int i = n + 1; i <= 6; ++i) val[i][i] = 1;

    int cnt = 0;
    for (int i = 1; i <= 6; ++i)
        for (int j = i + 1; j <= 6; ++j)
            for (int k = j + 1; k <= 6; ++k)
                mask[i][j][k] = 1 << cnt++;

    dfsA(1, 1, 1);
    L = (1 << 20) - 1;

    for (int b = 0; b < 20; ++b)
        for (int s = 0; s <= L; ++s)
            if (s >> b & 1)
                arr1[s] = (arr1[s] + arr1[s ^ (1 << b)]) % MOD;

    dfsB(1, 1, 4);
    res = (MOD + 1 - res) % MOD;
    printf("%d\n", res);
    return 0;
}
